-- =========================================================
-- Create the database
-- =========================================================

CREATE DATABASE CineRate;

USE CineRate;

-- =========================================================
-- Directors Table
-- =========================================================

CREATE TABLE Directors(
	DirectorID INT PRIMARY KEY IDENTITY(1,1),
	FullName NVARCHAR(100) NOT NULL,
	BirthDate DATE ,
	Nationality NVARCHAR(50) NOT NULL
); 

-- =========================================================
-- Movies Table
-- =========================================================

CREATE TABLE Movies(
	MovieID INT PRIMARY KEY IDENTITY(1,1),
	DirectorID INT FOREIGN KEY REFERENCES Directors (DirectorID),
	MovieTitle NVARCHAR(100) NOT NULL,
	ReleaseDate DATE NOT NULL,
	Duration INT ,
	MovieLanguage VARCHAR(50) NOT NULL,
	MovieDescription VARCHAR(500) NOT NULL,
	AgeRating VARCHAR(50) NOT NULL,
	MovieStatus VARCHAR(50) CHECK(MovieStatus IN ('Available','Archived')),
	PosterUrl VARCHAR(100) NOT NULL
);

-- =========================================================
-- Users Table
-- =========================================================

CREATE TABLE Users(
	UserID INT PRIMARY KEY IDENTITY(1,1),
	FullName NVARCHAR(100) NOT NULL,
	Email VARCHAR(50) NOT NULL UNIQUE ,
	UserPassword VARCHAR(50) NOT NULL,
	JoinDate DATE DEFAULT GETDATE()
);

-- =========================================================
-- Actors Table
-- =========================================================

CREATE TABLE Actors(
	ActorID INT PRIMARY KEY IDENTITY(1,1),
	FullName NVARCHAR(100) NOT NULL,
	BirthDate DATE ,
	Nationality NVARCHAR(50) NOT NULL
);

-- =========================================================
-- Genres Table
-- =========================================================

CREATE TABLE Genres(
	GenreID INT PRIMARY KEY IDENTITY(1,1),
	GenreName NVARCHAR(100) NOT NULL UNIQUE
);

-- =========================================================
-- Ratings Table
-- =========================================================

CREATE TABLE Ratings(
	RatingID INT PRIMARY KEY IDENTITY(1,1),
	UserID INT FOREIGN KEY REFERENCES Users (UserID),
	MovieID INT FOREIGN KEY REFERENCES Movies (MovieID),
	Score INT NOT NULL CHECK(Score>=1 AND Score<=10),
	RatingDate DATETIME DEFAULT GETDATE(),
	CONSTRAINT UQ_UserMovie_Rating UNIQUE(UserID, MovieID)
);

-- =========================================================
-- Reviews Table
-- =========================================================

CREATE TABLE Reviews(
	ReviewID INT PRIMARY KEY IDENTITY(1,1),
	UserID INT FOREIGN KEY REFERENCES Users (UserID),
	MovieID INT FOREIGN KEY REFERENCES Movies (MovieID),
	ReviewText NVARCHAR(500) NOT NULL ,
	ReviewDate DATETIME DEFAULT GETDATE(),
	CONSTRAINT UQ_UserMovie_Review UNIQUE(UserID, MovieID)
);

-- =========================================================
-- Watchlist Table
-- =========================================================

CREATE TABLE Watchlist(
	WatchlistID INT PRIMARY KEY IDENTITY(1,1),
	UserID INT FOREIGN KEY REFERENCES Users (UserID),
	MovieID INT FOREIGN KEY REFERENCES Movies (MovieID),
	MovieStatus VARCHAR(20) NOT NULL CHECK(MovieStatus IN('Planned','Watching','Watched')),
	AddedDate DATETIME DEFAULT GETDATE(),
	CONSTRAINT UQ_UserMovie_Watchlist UNIQUE(UserID, MovieID)
);

-- =========================================================
-- MovieGenres Table
-- =========================================================

CREATE TABLE MovieGenres(
	GenreID INT FOREIGN KEY REFERENCES Genres (GenreID),
	MovieID INT FOREIGN KEY REFERENCES Movies (MovieID),
	CONSTRAINT PK_MovieGenres PRIMARY KEY(GenreID, MovieID)
);

-- =========================================================
-- MovieActors Table
-- =========================================================

CREATE TABLE MovieActors(
	ActorID INT FOREIGN KEY REFERENCES Actors (ActorID),
	MovieID INT FOREIGN KEY REFERENCES Movies (MovieID),
	RoleName VARCHAR(20) NOT NULL,
	CONSTRAINT PK_MovieActors PRIMARY KEY(ActorID, MovieID)
);

