-- =========================================================
-- Find movies that are currently available, and  
-- Display movies from newest to oldest.
-- =========================================================
SELECT * FROM Movies
WHERE MovieStatus ='Available'
ORDER BY ReleaseDate DESC;

-- =========================================================
-- Find all different movie languages.
-- =========================================================
SELECT DISTINCT MovieLanguage FROM Movies;

-- =========================================================
-- Find directors from selected nationalities.
-- =========================================================
SELECT * FROM Directors
WHERE Nationality IN ('Egyptian', 'French');

-- =========================================================
-- Summary statistics over the whole rating data.
-- =========================================================
SELECT COUNT(*) AS TotalRatings,
	   MIN(Score)AS LowestScore,
	   MAX(Score)AS HighestScore,
	   AVG (Score) AS AvgScore
FROM Ratings;

-- =========================================================
-- Find ratings between 7 and 10.
-- =========================================================
SELECT RatingID , MovieID , UserID , Score
FROM Ratings
WHERE Score BETWEEN 7 AND 10
ORDER BY Score DESC;

-- =========================================================
-- Find movies whose title starts with "The".
-- =========================================================
SELECT MovieID , MovieTitle
FROM Movies
WHERE MovieTitle LIKE 'The%';

-- =========================================================
-- Average rating score, lowest rating score,
-- and number of ratings per movie.
-- =========================================================
SELECT Movies.MovieID , Movies.MovieTitle,
    COUNT(Ratings.RatingID) AS NumberOfRatings,
    MIN(Ratings.Score) AS LowestScore,
    AVG(Ratings.Score) AS AvgScore
FROM Movies
INNER JOIN Ratings 
    ON Movies.MovieID = Ratings.MovieID
GROUP BY Movies.MovieID, Movies.MovieTitle;

-- =========================================================
-- Find movies whose duration is greater than the average 
-- movie duration.
-- =========================================================
SELECT * FROM Movies
WHERE Duration > (
    SELECT AVG(Duration)
    FROM Movies
);

-- =========================================================
-- Find the top 3 movies with the highest average rating.
-- =========================================================
SELECT TOP 3
    Movies.MovieTitle,
    AVG(Ratings.Score) AS AverageRating
FROM Movies
INNER JOIN Ratings
    ON Movies.MovieID = Ratings.MovieID
GROUP BY Movies.MovieID, Movies.MovieTitle
ORDER BY AverageRating DESC;

-- =========================================================
-- Find movies, their actors, and the roles they play.
-- =========================================================
SELECT Movies.MovieTitle,
    Actors.FullName AS ActorName,
    MovieActors.RoleName
FROM Movies
INNER JOIN MovieActors
    ON Movies.MovieID = MovieActors.MovieID
INNER JOIN Actors
    ON MovieActors.ActorID = Actors.ActorID;